"""E12 blend (generated by notebooks/e12_blend/build.py; do not edit infer.py by hand).

Three readers, each a separate subprocess (GPU memory freed between), each writing per-study probabilities
(NaN = failed / not reached):
  ens4   ours, dataset aymenslimani/rsna-knee-v3-ens4 (v3_submission inference, 4 models rank-averaged)
  gpjw   goodpjw2008/rsna-knee-2-5d-convnext-reader (Apache-2.0), its own infer code, 3 folds
  raptor dreaddevelopment/raptor-knee-maxspan (CC0), CoAtNet maxspan, 62 windows (cut if too slow)
Blend: per finding, rank percentile over the studies each reader predicted; weighted mean with weights
renormalised over the readers that succeeded on that study. A study no reader predicted gets the column
mean of the blend (counted in the summary, never silent). fp16 autocast on CUDA only, never bf16.
"""
import json, os, subprocess, sys, time
from pathlib import Path

# ---- config ---------------------------------------------------------------------------------------------
WEIGHTS = {"raptor": 0.35, "gpjw": 0.35, "ens4": 0.30}
ORDER = ["ens4", "gpjw", "raptor"]  # slowest last: the deadline guard can shrink raptor's windows
TOTAL_BUDGET_S = 8.5 * 3600         # Kaggle limit is 9 h; margin for blend + write
# ----------------------------------------------------------------------------------------------------------

T0 = time.time()
DEADLINE = T0 + TOTAL_BUDGET_S
SOURCES = {'ens4': '"""V3 offline submission inference (generated by build.py; do not edit infer.py by hand).\n\nEnsemble: CONFIG["models"] lists checkpoints, each with its own head / windows / res / mirror. Each\nstudy is read and canonicalised ONCE; windows are filled per (mirror, windows) and every model runs on\nit. Per-model probabilities go to probs_<name>.csv; submission = per-finding rank percentile over test\nstudies, equal-weight mean over the models that succeeded on that study (single model: raw probs).\n\nPreprocessing = cache + train_v3 eval exactly: select_series -> canon.canon_series (bundled\nverbatim, SHA-checked) -> optional L->R mirror -> evenly spaced 3-slice windows -> /255, resize to\nRES, ImageNet norm -> V3 model. fp16 autocast on GPU (never bf16), fp32 on CPU, batch 1.\nNo training labels are opened.\n\nFailure policy (every case counted in the summary, never silent):\n  1. all selected series load -> normal prediction;\n  2. a series fails -> drop only that plane ("degraded");\n  3. no plane left -> column mean of successful predictions ("fallback"; never 0.5); same after 8 h.\nPARITY_UIDS set -> parity mode: those train studies from train_series, writes probs_<name>.csv, no submission.\n"""\nimport csv\nimport hashlib\nimport json\nimport os\nimport sys\nimport time\nfrom collections import Counter, defaultdict\nfrom pathlib import Path\n\nimport numpy as np\nimport pydicom\nimport torch\nfrom scipy.stats import rankdata\nfrom torch.utils.data import DataLoader, Dataset\n\nSOURCES = {\'m00_data.py\': \'"""M00 data path: series selection, DICOM ordering/scaling, window sampling, study tensor.\\n\\nOffline, deterministic, no flips. Failures raise SeriesError (series-level) or StudyError\\n(study-level) so callers can count them; nothing is silently substituted.\\n"""\\nimport numpy as np\\nimport torch\\nimport torch.nn.functional as F\\n\\nROLES = ("Sagittal", "Coronal", "Axial")\\nTRAIN_WINDOWS, INFER_WINDOWS, SIZE = 4, 16, 224\\nTOL_MM = 1e-3\\n\\n\\nclass SeriesError(ValueError):\\n    pass\\n\\n\\nclass StudyError(ValueError):\\n    pass\\n\\n\\ndef select_series(rows):\\n    """rows: iterable of dicts with SeriesInstanceUID, Fluid_Sensitive, Fat_Suppression,\\n    Anatomical_Plane (official train_series.csv fields) for ONE study.\\n    Returns {role: SeriesInstanceUID or None}. Deterministic.\\n    ponytail: preference fluid-sensitive > fat-suppressed > smallest UID is MY choice, not a\\n    clinical rule; revisit after the A05 role study."""\\n    best = {r: None for r in ROLES}\\n    for row in rows:\\n        role = str(row["Anatomical_Plane"]).strip().capitalize()\\n        if role not in best:\\n            continue\\n        key = (-int(row["Fluid_Sensitive"] or 0), -int(row["Fat_Suppression"] or 0),\\n               str(row["SeriesInstanceUID"]))\\n        if best[role] is None or key < best[role][0]:\\n            best[role] = (key, str(row["SeriesInstanceUID"]))\\n    return {r: (v[1] if v else None) for r, v in best.items()}\\n\\n\\nSLOTS6 = tuple((p, f) for p in ROLES for f in (1, 0))  # plane x {fat-sat, non-fat-sat}\\n\\n\\ndef slot_names(n):\\n    return ROLES if n == 3 else SLOTS6\\n\\n\\ndef select_slots(rows, n=3):\\n    """n=3: select_series. n=6: {(plane, fatsat): uid or None}, same preference rule within each slot."""\\n    rows = list(rows)\\n    if n == 3:\\n        return select_series(rows)\\n    assert n == 6, n\\n    return {(p, f): select_series([r for r in rows if int(r["Fat_Suppression"] or 0) == f])[p] for p, f in SLOTS6}\\n\\ndef slice_position(ds):\\n    """Projection of ImagePositionPatient on row x col normal; None if tags missing."""\\n    iop, ipp = getattr(ds, "ImageOrientationPatient", None), getattr(ds, "ImagePositionPatient", None)\\n    if iop is None or ipp is None:\\n        return None\\n    iop, ipp = np.asarray(iop, float), np.asarray(ipp, float)\\n    if iop.shape != (6,) or ipp.shape != (3,) or not (np.isfinite(iop).all() and np.isfinite(ipp).all()):\\n        raise SeriesError("malformed orientation/position tags")\\n    r, c = iop[:3], iop[3:]\\n    if abs(np.linalg.norm(r) - 1) > 1e-2 or abs(np.linalg.norm(c) - 1) > 1e-2 or abs(r @ c) > 1e-2:\\n        raise SeriesError("ImageOrientationPatient not orthonormal")\\n    return float(ipp @ np.cross(r, c)), tuple(np.round(np.cross(r, c), 3))\\n\\n\\ndef order_slices(datasets):\\n    """Sort datasets by physical position. Fallback to InstanceNumber ONLY if every slice lacks\\n    orientation/position tags; mixed presence, duplicates, irregular gaps or in-plane changes raise."""\\n    if not datasets:\\n        raise SeriesError("empty series")\\n    spacings = []\\n    for ds in datasets:\\n        raw = getattr(ds, "PixelSpacing", None)\\n        if raw is None:\\n            raise SeriesError("missing PixelSpacing")\\n        spacing = np.asarray(raw, dtype=float)\\n        if spacing.shape != (2,) or not np.isfinite(spacing).all() or np.any(spacing <= 0):\\n            raise SeriesError("invalid PixelSpacing")\\n        spacings.append(spacing)\\n    if any(np.max(np.abs(spacing - spacings[0])) > 1e-3 for spacing in spacings[1:]):\\n        raise SeriesError("pixel spacing differs within series")\\n    pos = [slice_position(d) for d in datasets]\\n    if all(p is None for p in pos):\\n        nums = [getattr(d, "InstanceNumber", None) for d in datasets]\\n        if any(n is None for n in nums) or len(set(int(n) for n in nums)) != len(nums):\\n            raise SeriesError("no geometry tags and InstanceNumber missing/duplicated")\\n        keys = [float(n) for n in nums]\\n    elif any(p is None for p in pos):\\n        raise SeriesError("geometry tags present on only some slices")\\n    else:\\n        if len({p[1] for p in pos}) != 1:\\n            raise SeriesError("slice normal differs within series")\\n        orientation = np.asarray(datasets[0].ImageOrientationPatient, dtype=float)\\n        if any(np.max(np.abs(np.asarray(ds.ImageOrientationPatient, dtype=float) - orientation)) > 1e-3\\n               for ds in datasets[1:]):\\n            raise SeriesError("in-plane orientation differs within series")\\n        keys = [p[0] for p in pos]\\n    order = np.argsort(keys, kind="stable")\\n    s = np.asarray(keys)[order]\\n    if len(s) > 1 and np.diff(s).min() < TOL_MM:\\n        raise SeriesError("duplicate slice positions")\\n    if len(s) > 2:\\n        gaps = np.diff(s)\\n        if gaps.max() > 1.5 * np.median(gaps) + 0.01:\\n            raise SeriesError("irregular slice gap")\\n    return [datasets[i] for i in order]\\n\\n\\ndef slice_pixels(ds):\\n    """float32 pixels after rescale and MONOCHROME1 inversion (negation; scaling is affine)."""\\n    a = ds.pixel_array.astype(np.float32)\\n    if a.ndim != 2:\\n        raise SeriesError("non-2D pixel array")\\n    a = a * float(getattr(ds, "RescaleSlope", 1.0)) + float(getattr(ds, "RescaleIntercept", 0.0))\\n    if str(getattr(ds, "PhotometricInterpretation", "MONOCHROME2")) == "MONOCHROME1":\\n        a = -a\\n    return a\\n\\n\\ndef load_series(datasets, lo_q=1.0, hi_q=99.0):\\n    """-> (volume [N,H,W] float32 in [0,1], slice_ok [N] bool). Slices with nonfinite values or\\n    constant content are flagged not-ok (zero-filled, never used in a window)."""\\n    ds = order_slices(datasets)\\n    arrs = [slice_pixels(d) for d in ds]\\n    if len({a.shape for a in arrs}) != 1:\\n        raise SeriesError("inconsistent slice shapes")\\n    ok = np.array([np.isfinite(a).all() and a.max() > a.min() for a in arrs])\\n    if ok.sum() < 3:\\n        raise SeriesError("fewer than 3 usable slices")\\n    # Bound percentile scratch memory for large series while sampling each slice\\n    # deterministically. Full decoded slices are still used for final scaling.\\n    vals = np.concatenate([\\n        a.ravel()[::max(1, a.size // 16384)] for a, k in zip(arrs, ok) if k\\n    ])\\n    lo, hi = np.percentile(vals, [lo_q, hi_q])\\n    if not hi > lo:\\n        raise SeriesError("degenerate intensity range")\\n    vol = np.stack([np.clip((a - lo) / (hi - lo), 0, 1) if k else np.zeros_like(a)\\n                    for a, k in zip(arrs, ok)]).astype(np.float32)\\n    return vol, ok\\n\\n\\ndef window_centers(ok, n, rng=None):\\n    """Centers c such that slices c-1,c,c+1 are all usable (physically adjacent in sorted order).\\n    rng None -> deterministic evenly spaced (inference); else random without replacement (train)."""\\n    valid = np.flatnonzero(ok[:-2] & ok[1:-1] & ok[2:]) + 1\\n    if len(valid) == 0:\\n        return valid\\n    if rng is None:\\n        return np.unique(valid[np.round(np.linspace(0, len(valid) - 1, n)).astype(int)])\\n    return np.sort(rng.choice(valid, size=min(n, len(valid)), replace=False))\\n\\n\\ndef series_windows(vol, ok, n, rng=None):\\n    """-> (x [n,3,224,224], mask [n]); unused rows zero with mask False."""\\n    x = torch.zeros(n, 3, SIZE, SIZE)\\n    m = torch.zeros(n, dtype=torch.bool)\\n    for i, c in enumerate(window_centers(ok, n, rng)):\\n        w = torch.from_numpy(vol[c - 1:c + 2])[None]\\n        x[i] = F.interpolate(w, size=(SIZE, SIZE), mode="bilinear", align_corners=False)[0]\\n        m[i] = True\\n    return x, m\\n\\n\\ndef build_study(role_series, train, rng=None):\\n    """role_series: {role: (vol, ok) or None}. -> (x [3,W,3,224,224], mask [3,W]).\\n    Raises StudyError if no role yields a valid window."""\\n    n = TRAIN_WINDOWS if train else INFER_WINDOWS\\n    xs, ms = [], []\\n    for r in ROLES:\\n        s = role_series.get(r)\\n        x, m = series_windows(*s, n, rng if train else None) if s else (\\n            torch.zeros(n, 3, SIZE, SIZE), torch.zeros(n, dtype=torch.bool))\\n        xs.append(x), ms.append(m)\\n    mask = torch.stack(ms)\\n    if not mask.any():\\n        raise StudyError("study has no valid window in any role")\\n    return torch.stack(xs), mask\\n\', \'m00_model.py\': \'"""M00: random-init ResNet18 shared encoder, shared max over valid windows (all roles jointly),\\none linear head -> 12 logits. No pretrained weights, no network access."""\\nimport torch\\nimport torch.nn as nn\\nimport torch.nn.functional as F\\nfrom torchvision.models import resnet18\\n\\nTARGETS = ["ACL", "MCL", "Medial Meniscus", "Lateral Meniscus", "Medial OA", "Lateral OA",\\n           "PF OA", "Effusion", "Synovitis", "Baker\\\'s", "Contusion", "Fracture"]\\n\\n\\nclass M00(nn.Module):\\n    def __init__(self):\\n        super().__init__()\\n        self.encoder = resnet18(weights=None)\\n        self.encoder.fc = nn.Identity()\\n        self.head = nn.Linear(512, len(TARGETS))\\n\\n    def forward(self, x, mask):\\n        """x [B,R,W,3,H,W2] float, mask [B,R,W] bool -> logits [B,12]. Only valid windows are\\n        encoded, so padded windows cannot influence features, BatchNorm stats or the max."""\\n        if x.ndim != 6 or x.shape[3] != 3 or mask.dtype != torch.bool or mask.shape != x.shape[:3]:\\n            raise ValueError(f"bad shapes x={tuple(x.shape)} mask={tuple(mask.shape)} {mask.dtype}")\\n        has = mask.flatten(1).any(1)\\n        if not has.all():\\n            raise ValueError(f"studies with no valid window (batch idx {(~has).nonzero().flatten().tolist()})")\\n        sel = x[mask]\\n        if not torch.isfinite(sel).all():\\n            raise ValueError("nonfinite pixels in a valid window")\\n        feats = self.encoder(sel)                                   # [n,512]\\n        b = mask.flatten(1).nonzero()[:, 0]                         # study index per valid window\\n        pooled = feats.new_full((x.shape[0], feats.shape[1]), float("-inf"))\\n        pooled = pooled.scatter_reduce(0, b[:, None].expand_as(feats), feats, "amax", include_self=True)\\n        return self.head(pooled)\\n\\n\\n@torch.no_grad()\\ndef predict_proba(model, x, mask):\\n    """Finite [B,12] probabilities in [0,1] or a clear error."""\\n    model.eval()\\n    p = torch.sigmoid(model(x, mask))\\n    if not torch.isfinite(p).all():\\n        raise FloatingPointError("nonfinite probabilities")\\n    return p\\n\\n\\ndef masked_bce(logits, targets, observed):\\n    """Mean BCE over observed cells only. observed bool [B,12]; unobserved targets ignored."""\\n    if logits.shape != targets.shape or logits.shape != observed.shape or observed.dtype != torch.bool:\\n        raise ValueError("logits, targets and boolean observed mask must have identical shapes")\\n    if not observed.any():\\n        raise ValueError("no observed targets in batch")\\n    selected_logits, selected_targets = logits[observed], targets[observed].float()\\n    if not torch.isfinite(selected_logits).all() or not torch.isfinite(selected_targets).all():\\n        raise ValueError("nonfinite observed logits or targets")\\n    return F.binary_cross_entropy_with_logits(selected_logits, selected_targets)\\n\', \'canon.py\': \'"""V3 canonical series preprocessing, shared by the cache builder and offline inference.\\n\\ncanon_series(datasets or paths) -> (uint8 [N,256,256], meta):\\n  IPP-projected slice order (m00_data.order_slices), slices ascending along +LPS axis of the\\n  dominant normal; in-plane flips/transposes only (no interpolation) so that\\n    sagittal: cols -> +y (posterior), rows -> -z (inferior)\\n    coronal:  cols -> +x (patient left), rows -> -z\\n    axial:    cols -> +x, rows -> +y\\n  160 mm physical square centre crop/pad, antialiased area resize to 256 px (0.625 mm/px),\\n  foreground (Otsu) p0.5-p99.8 -> uint8. Laterality is only reported (meta), never applied.\\n"""\\nimport numpy as np\\nimport torch\\nimport torch.nn.functional as F\\n\\nfrom m00_data import SeriesError, order_slices, slice_pixels, slice_position\\n\\nOUT_PX, CROP_MM, LO_Q, HI_Q, LAT_MM = 256, 160.0, 0.5, 99.8, 20.0\\nAXES = np.eye(3)\\n# normal axis -> (target col direction, target row direction) in LPS\\nTARGETS = {0: (AXES[1], -AXES[2]), 1: (AXES[0], -AXES[2]), 2: (AXES[0], AXES[1])}\\nPLANE = {0: "Sagittal", 1: "Coronal", 2: "Axial"}\\n\\n\\ndef _otsu(v):\\n    hist, edges = np.histogram(v, 256)\\n    c = (edges[:-1] + edges[1:]) / 2\\n    w0 = np.cumsum(hist).astype(float)\\n    w1 = w0[-1] - w0\\n    s0 = np.cumsum(hist * c)\\n    with np.errstate(divide="ignore", invalid="ignore"):\\n        var = w0 * w1 * (s0 / w0 - (s0[-1] - s0) / w1) ** 2\\n    return c[int(np.nanargmax(var[:-1]))]\\n\\n\\ndef _fit(a, n, axis, fill):\\n    """Centre crop or symmetric pad `a` to length n along axis."""\\n    h = a.shape[axis]\\n    if h < n:\\n        pad = [(0, 0)] * a.ndim\\n        pad[axis] = ((n - h) // 2, n - h - (n - h) // 2)\\n        return np.pad(a, pad, constant_values=fill)\\n    s = (h - n) // 2\\n    return a[(slice(None),) * axis + (slice(s, s + n),)]\\n\\n\\ndef _laterality(ds, r, c, sp):\\n    for tag in ("Laterality", "ImageLaterality"):\\n        v = str(getattr(ds, tag, "") or "").strip().upper()[:1]\\n        if v in ("L", "R"):\\n            return v, "tag", float("nan")\\n    ctr = (np.asarray(ds.ImagePositionPatient, float) + r * sp[1] * (int(ds.Columns) - 1) / 2\\n           + c * sp[0] * (int(ds.Rows) - 1) / 2)\\n    x = float(ctr[0])\\n    return ("L" if x > LAT_MM else "R" if x < -LAT_MM else "U"), "ipp_x", x\\n\\n\\ndef canon_series(datasets):\\n    if datasets and not hasattr(datasets[0], "pixel_array"):\\n        import pydicom\\n        datasets = [pydicom.dcmread(str(p)) for p in datasets]\\n    ds = order_slices(datasets)\\n    if slice_position(ds[0]) is None:\\n        raise SeriesError("no orientation tags; cannot canonicalise")\\n    iop = np.asarray(ds[0].ImageOrientationPatient, float)\\n    r0, c0 = iop[:3], iop[3:]\\n    n = np.cross(r0, c0)\\n    ax = int(np.argmax(np.abs(n)))\\n    if n[ax] < 0:  # ascending along +axis\\n        ds, n = ds[::-1], -n\\n    pos = np.array([float(np.asarray(d.ImagePositionPatient, float) @ n) for d in ds])\\n    sp = np.asarray(ds[0].PixelSpacing, float)  # (row spacing, col spacing)\\n    lat, lat_src, ctr_x = _laterality(ds[len(ds) // 2], r0, c0, sp)\\n\\n    tc, tr = TARGETS[ax]\\n    transpose = abs(r0 @ tc) < abs(c0 @ tc)\\n    r, c = (c0, r0) if transpose else (r0, c0)\\n    if transpose:\\n        sp = sp[::-1]\\n    flip_c, flip_r = bool(r @ tc < 0), bool(c @ tr < 0)\\n    ch, cw = (int(round(CROP_MM / s)) for s in sp)\\n    if len({(int(d.Rows), int(d.Columns)) for d in ds}) != 1:\\n        raise SeriesError("inconsistent slice shapes")\\n\\n    out, bad = [], 0\\n    for d in ds:\\n        a = slice_pixels(d)\\n        if not np.isfinite(a).all() or a.max() <= a.min():\\n            bad += 1\\n            a = np.nan_to_num(a, nan=0.0, posinf=0.0, neginf=0.0)\\n        if transpose:\\n            a = a.T\\n        a = a[::-1 if flip_r else 1, ::-1 if flip_c else 1]\\n        fill = float(a.min())\\n        a = _fit(_fit(a, ch, 0, fill), cw, 1, fill)\\n        t = torch.from_numpy(np.ascontiguousarray(a, dtype=np.float32))[None, None]\\n        mode = "area" if min(ch, cw) >= OUT_PX else "bilinear"\\n        out.append(F.interpolate(t, size=(OUT_PX, OUT_PX), mode=mode,\\n                                 **({"align_corners": False} if mode == "bilinear" else {}))[0, 0].numpy())\\n    vol = np.stack(out)\\n    v = vol.ravel()[:: max(1, vol.size // 2_000_000)]\\n    fg = v[v > _otsu(v)]\\n    if fg.size < 0.01 * v.size:\\n        fg = v\\n    lo, hi = (float(x) for x in np.percentile(fg, [LO_Q, HI_Q]))\\n    if not hi > lo:  # flat foreground: fall back to all pixels\\n        lo, hi = (float(x) for x in np.percentile(v, [LO_Q, HI_Q]))\\n    if not hi > lo:\\n        raise SeriesError("degenerate intensity range")\\n    img = np.round(np.clip((vol - lo) / (hi - lo), 0, 1) * 255).astype(np.uint8)\\n    meta = {\\n        "plane_geom": PLANE[ax], "n": len(ds), "positions": pos.tolist(),\\n        "row_spacing": float(sp[0]), "col_spacing": float(sp[1]),\\n        "thickness": float(getattr(ds[0], "SliceThickness", None) or "nan"),\\n        "laterality": lat, "laterality_source": lat_src, "centre_x_mm": ctr_x,\\n        "lo": lo, "hi": hi, "transpose": bool(transpose), "flip_rows": flip_r, "flip_cols": flip_c,\\n        "bad_slices": bad, "orig_shape": (int(ds[0].Rows), int(ds[0].Columns)),\\n    }\\n    return img, meta\\n\', \'v3_model.py\': \'"""V3 shared eval path: mirror, window selection, normalisation, model heads.\\nUsed by src/train_v3.py and bundled verbatim into notebooks/v3_submission (parity depends on it)."""\\nimport numpy as np\\nimport torch\\nimport torch.nn as nn\\nimport torch.nn.functional as F\\n\\nfrom m00_data import ROLES, window_centers\\nfrom m00_model import M00, TARGETS\\n\\nMEAN = torch.tensor([0.485, 0.456, 0.406]).view(1, 3, 1, 1)\\nSTD = torch.tensor([0.229, 0.224, 0.225]).view(1, 3, 1, 1)\\n\\n\\ndef mirror(vol, plane):\\n    """Patient L<->R mirror in canonical cache space: sagittal slices run along +x, so reverse\\n    slice order; coronal/axial columns run along +x, so flip columns. Self-inverse."""\\n    return vol[::-1] if plane == "Sagittal" else vol[..., ::-1]\\n\\n\\ndef fill_windows(x, m, vol, n, rng=None):\\n    """Write up to n 3-slice windows of uint8 vol [L,S,S] into x [n,3,S,S], m [n].\\n    rng None -> evenly spaced centres (eval, --slab); else random (P00 train).\\n    ponytail: all slices treated usable (cache nan-fills bad slices; bad_slices=0 so far)."""\\n    for k, c in enumerate(window_centers(np.ones(len(vol), bool), n, rng)):\\n        x[k], m[k] = vol[c - 1:c + 2], True\\n\\n\\ndef prep(x, res):\\n    """uint8 [B,R,W,3,S,S] -> ImageNet-normalised float [B,R,W,3,res,res] (same device)."""\\n    lead = x.shape[:3]\\n    x = x.flatten(0, 2).float().div_(255)\\n    if res != x.shape[-1]:\\n        x = F.interpolate(x, size=(res, res), mode="bilinear", antialias=True, align_corners=False)\\n    x = (x - MEAN.to(x.device)) / STD.to(x.device)\\n    return x.view(*lead, 3, res, res)\\n\\n\\nTIMM = {"convnext_tiny": "convnext_tiny.fb_in22k_ft_in1k"}  # same ImageNet mean/std as MEAN/STD\\n\\n\\nclass V3(M00):\\n    """head=\\\'max\\\': exactly M00/P00 (same state_dict keys). head=\\\'attn\\\': per-finding gated\\n    attention-MIL (Ilse 2018) over all valid windows of all planes + learned per-finding plane\\n    bias; logit_f = <pooled_f, head.weight[f]> + head.bias[f]."""\\n\\n    def __init__(self, head="max", hidden=128, backbone="resnet18"):\\n        super().__init__()\\n        self.head_type = head\\n        if backbone != "resnet18":  # timm encoder, random init; weights come from pretrained/checkpoint\\n            import timm\\n            self.encoder = timm.create_model(TIMM[backbone], pretrained=False, num_classes=0)\\n            self.head = nn.Linear(self.encoder.num_features, len(TARGETS))\\n        d = self.head.in_features\\n        if head == "attn":\\n            self.att_v = nn.Linear(d, hidden)\\n            self.att_u = nn.Linear(d, hidden)\\n            self.att_w = nn.Linear(hidden, len(TARGETS))\\n            self.plane_bias = nn.Parameter(torch.zeros(len(ROLES), len(TARGETS)))\\n        elif head != "max":\\n            raise ValueError(head)\\n\\n    def forward(self, x, mask):\\n        if self.head_type == "max":\\n            return super().forward(x, mask)\\n        if x.ndim != 6 or mask.shape != x.shape[:3] or not mask.flatten(1).any(1).all():\\n            raise ValueError(f"bad shapes / empty study x={tuple(x.shape)} mask={tuple(mask.shape)}")\\n        feats = self.encoder(x[mask])                                       # [n,d]\\n        h = feats.new_zeros(*mask.shape, feats.shape[1])\\n        h[mask] = feats                                                      # [B,R,W,512]\\n        a = self.att_w(torch.tanh(self.att_v(h)) * torch.sigmoid(self.att_u(h)))  # [B,R,W,12]\\n        a = (a.float() + self.plane_bias[None, :, None]).masked_fill(~mask[..., None], float("-inf"))\\n        a = a.flatten(1, 2).softmax(1)                                       # [B,R*W,12]\\n        pooled = torch.einsum("bnf,bnd->bfd", a, h.flatten(1, 2).float())    # [B,12,512]\\n        return (pooled * self.head.weight.float()).sum(-1) + self.head.bias.float()\\n\'}\nCONFIG = {\'dataset\': \'rsna-knee-v3-ens4\', \'models\': [{\'name\': \'e45\', \'checkpoint\': \'e45.pt\', \'sha256\': \'d518bd339c60f0bc99ad12a08c6a74e64b28a0369f4e7f9fbe84305d6adcdab5\', \'source\': \'C:\\\\Users\\\\msi\\\\Downloads\\\\kaggle project RSNA\\\\kaggle project RSNA\\\\V2_new_research\\\\outputs\\\\e45_v3\\\\best.pt\', \'head\': \'max\', \'backbone\': \'resnet18\', \'windows\': 16, \'res\': 224, \'mirror\': True, \'slots\': 3}, {\'name\': \'e6\', \'checkpoint\': \'e6.pt\', \'sha256\': \'965bbf0a18d15cb33f89294897d5e691e9587362198036a12c9172b8588961d5\', \'source\': \'C:\\\\Users\\\\msi\\\\Downloads\\\\kaggle project RSNA\\\\kaggle project RSNA\\\\V2_new_research\\\\outputs\\\\e6_v3\\\\ep16.pt\', \'head\': \'max\', \'backbone\': \'resnet18\', \'windows\': 16, \'res\': 224, \'mirror\': True, \'slots\': 3}, {\'name\': \'e2\', \'checkpoint\': \'e2.pt\', \'sha256\': \'31b9a7105b3b7efbdddf2200e9365795da7377bc42afe9d27d460fc3e00311a0\', \'source\': \'C:\\\\Users\\\\msi\\\\Downloads\\\\kaggle project RSNA\\\\kaggle project RSNA\\\\V2_new_research\\\\outputs\\\\e2_v3\\\\best.pt\', \'head\': \'attn\', \'backbone\': \'resnet18\', \'windows\': 12, \'res\': 224, \'mirror\': True, \'slots\': 3}, {\'name\': \'e8\', \'checkpoint\': \'e8.pt\', \'sha256\': \'ad0ce4c9ec6d3e41026631b219fa1b821b83d318575753a88cc970fcfad4114c\', \'source\': \'C:\\\\Users\\\\msi\\\\Downloads\\\\kaggle project RSNA\\\\kaggle project RSNA\\\\V2_new_research\\\\outputs\\\\e8_cnxt\\\\best.pt\', \'head\': \'max\', \'backbone\': \'convnext_tiny\', \'windows\': 16, \'res\': 224, \'mirror\': True, \'slots\': 3}], \'source_sha256\': {\'m00_data.py\': \'8868de34804457cf1911367eef59205fd5a5e60bf30ba7b4fa1193e27b0ebb41\', \'m00_model.py\': \'e8410ff5ebcfcf2036c5da18538fc194fe6db24eb88f274981bfba9de3ed531e\', \'canon.py\': \'55edc8e20e7bb5a9b2167dbb6286af358ad84c46a46d239dfbbebc477e1417b1\', \'v3_model.py\': \'1d65aae3f351fcd0269b188238bb4022c20b24a6e021e5ef17f600b64ea3cc1c\'}, \'run\': [{\'name\': \'e45\', \'head\': \'max\', \'windows\': 16, \'res\': 224, \'mirror\': True, \'slots\': 3}, {\'name\': \'e6\', \'head\': \'max\', \'windows\': 16, \'res\': 224, \'mirror\': True, \'slots\': 3}, {\'name\': \'e2\', \'head\': \'attn\', \'windows\': 12, \'res\': 224, \'mirror\': True, \'slots\': 3}, {\'name\': \'e8\', \'head\': \'max\', \'windows\': 16, \'res\': 224, \'mirror\': True, \'slots\': 3}]}\nPARITY_UIDS = None\n\nSRC = Path("/tmp/v3src") if Path("/kaggle").is_dir() else Path(__file__).resolve().parent / "_v3src"\nSRC.mkdir(parents=True, exist_ok=True)\nfor name, text in SOURCES.items():\n    if hashlib.sha256(text.encode("utf-8")).hexdigest() != CONFIG["source_sha256"][name]:\n        raise ValueError(f"source hash mismatch: {name}")\n    (SRC / name).write_text(text, encoding="utf-8")\nsys.path.insert(0, str(SRC))\nfrom canon import canon_series  # noqa: E402\nfrom m00_data import ROLES, select_series, select_slots, slot_names  # noqa: E402,F401\nfrom v3_model import V3, TARGETS, fill_windows, mirror, prep  # noqa: E402\n\nCOMPETITION_DIRS = (Path("/kaggle/input/rsna-knee-abnormality-detection"),\n                    Path("/kaggle/input/competitions/rsna-knee-abnormality-detection"))\nCHECKPOINT_DIRS = (Path("/kaggle/input") / CONFIG["dataset"],\n                   Path("/kaggle/input/datasets/aymenslimani") / CONFIG["dataset"])\nOUT = Path(os.environ.get("E12_OUT", "."))\nSTOP_AT_S = float(os.environ.get("E12_DEADLINE", time.time() + 8 * 3600)) - time.time()\nWORKERS = 4\nVIEWS = sorted({(m["mirror"], m["windows"], m.get("slots", 3)) for m in CONFIG["models"]})\nT0 = time.monotonic()\n\n\ndef sha256(path):\n    h = hashlib.sha256()\n    with path.open("rb") as f:\n        for chunk in iter(lambda: f.read(1 << 20), b""):\n            h.update(chunk)\n    return h.hexdigest()\n\n\ndef exactly_one(name, directories):\n    hits = {p.resolve() for d in directories if d.is_dir() for p in d.rglob(name)}\n    if len(hits) != 1:\n        raise FileNotFoundError(f"expected one {name}, found {len(hits)}")\n    return hits.pop()\n\n\ndef read_csv(path):\n    with path.open(newline="", encoding="utf-8-sig") as f:\n        return list(csv.DictReader(f))\n\n\ndef read_schema(data):\n    if PARITY_UIDS is not None:\n        cols, uids, series_csv = ["StudyInstanceUID", *TARGETS], list(PARITY_UIDS), "train_series.csv"\n    else:\n        rows = read_csv(data / "sample_submission.csv")\n        cols = list(rows[0]) if rows else []\n        if cols != ["StudyInstanceUID", *TARGETS]:\n            raise ValueError("sample submission schema mismatch or empty")\n        uids = [r["StudyInstanceUID"] for r in rows]\n        if len(uids) != len(set(uids)) or set(uids) != {r["StudyInstanceUID"] for r in read_csv(data / "test.csv")}:\n            raise ValueError("duplicate sample UID or test/sample UIDs differ")\n        series_csv = "test_series.csv"\n    by_study = defaultdict(list)\n    for row in read_csv(data / series_csv):\n        by_study[row["StudyInstanceUID"]].append(row)\n    return cols, uids, by_study\n\n\nclass TestDS(Dataset):\n    def __init__(self, root, uids, by_study):\n        self.root, self.uids, self.by_study = root, uids, by_study\n\n    def __len__(self):\n        return len(self.uids)\n\n    def __getitem__(self, i):\n        uid = self.uids[i]\n        syntaxes, errors = Counter(), []\n        vols, xs, ms, selected = {}, {}, {}, set()\n        for n_slots in sorted({v[2] for v in VIEWS}):\n            slots = slot_names(n_slots)\n            sel = select_slots(self.by_study.get(uid, []), n_slots)\n            for v in VIEWS:\n                if v[2] == n_slots:\n                    xs[v], ms[v] = np.zeros((len(slots), v[1], 3, 256, 256), np.uint8), np.zeros((len(slots), v[1]), bool)\n            for r, slot in enumerate(slots):\n                series = sel[slot]\n                if series is None:\n                    continue  # missing slot stays masked\n                selected.add(series)\n                if series not in vols:  # each series decoded once, shared by every slot config\n                    try:\n                        paths = sorted((self.root / uid / series).glob("*.dcm"))\n                        if not paths:\n                            raise FileNotFoundError("selected series has no DICOM files")\n                        dss = [pydicom.dcmread(str(p)) for p in paths]\n                        syntaxes[str(getattr(dss[0].file_meta, "TransferSyntaxUID", "?"))] += 1\n                        vol, meta = canon_series(dss)\n                        if len(vol) < 3:\n                            raise ValueError("fewer than 3 slices")\n                        vols[series] = (vol, mirror(vol, meta["plane_geom"]) if meta["laterality"] == "L" else vol)\n                    except Exception as exc:\n                        errors.append(f"{slot}:{type(exc).__name__}")\n                        vols[series] = None\n                if vols[series] is None:\n                    continue\n                for v in VIEWS:\n                    if v[2] == n_slots:\n                        fill_windows(xs[v][r], ms[v][r], vols[series][v[0]], v[1])\n        state = "failed" if not ms[VIEWS[0]].any() else "degraded" if errors else "ok"\n        return {"i": i, "state": state, "x": {v: torch.from_numpy(a) for v, a in xs.items()},\n                "mask": {v: torch.from_numpy(a) for v, a in ms.items()},\n                "syntaxes": syntaxes, "errors": errors, "n_selected_series": len(selected)}\n\n\ndef write_csv(path, columns, uids, values):\n    tmp = path.with_name(path.name + ".tmp")\n    with tmp.open("w", newline="", encoding="utf-8") as f:\n        w = csv.writer(f, lineterminator="\\n")\n        w.writerow(columns)\n        for uid, p in zip(uids, values):\n            w.writerow([uid, *[format(float(v), ".9g") for v in p]])\n    os.replace(tmp, path)\n\n\ndef worker_init(_):\n    torch.set_num_threads(1)\n\n\ndef main():\n    data = next((p for p in COMPETITION_DIRS if (p / "sample_submission.csv").is_file()), None)\n    if data is None:\n        raise FileNotFoundError("official competition data mount missing")\n    columns, uids, by_study = read_schema(data)\n    root = data / ("train_series" if PARITY_UIDS is not None else "test_series")\n    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")\n    print(f"device={device} torch={torch.__version__} pydicom={pydicom.__version__} studies={len(uids)} models={CONFIG[\'run\']}", flush=True)\n    models = []\n    for spec in CONFIG["models"]:\n        checkpoint = exactly_one(spec["checkpoint"], CHECKPOINT_DIRS)\n        if sha256(checkpoint) != spec["sha256"]:\n            raise ValueError(f"checkpoint SHA256 mismatch: {spec[\'name\']}")\n        model = V3(spec["head"], backbone=spec.get("backbone", "resnet18")).to(device).eval()\n        model.load_state_dict(torch.load(checkpoint, map_location="cpu", weights_only=True), strict=True)\n        models.append((spec, model))\n\n    loader = DataLoader(TestDS(root, uids, by_study), batch_size=None, shuffle=False, num_workers=WORKERS,\n                        worker_init_fn=worker_init, multiprocessing_context="fork" if sys.platform == "linux" else None)\n    probs = np.full((len(models), len(uids), len(TARGETS)), np.nan)\n    states, syntaxes, errors, windows, model_failures = Counter(), Counter(), Counter(), [], Counter()\n    timed_out = 0\n    for n, item in enumerate(loader, 1):\n        if time.monotonic() - T0 > STOP_AT_S:\n            timed_out = len(uids) - n + 1\n            print(f"time limit reached; {timed_out} studies left for fallback", flush=True)\n            break\n        states[item["state"]] += 1\n        syntaxes.update(item["syntaxes"])\n        errors.update(item["errors"])\n        if item["state"] == "failed":\n            print(f"study {item[\'i\']} FAILED: {item[\'errors\']} (selected series {item[\'n_selected_series\']})", flush=True)\n            continue\n        if item["state"] == "degraded":\n            print(f"study {item[\'i\']} degraded: {item[\'errors\']}", flush=True)\n        windows.append(int(item["mask"][VIEWS[0]].sum()))\n        for k, (spec, model) in enumerate(models):\n            try:\n                view = (spec["mirror"], spec["windows"], spec.get("slots", 3))\n                x, mask = item["x"][view][None].to(device), item["mask"][view][None].to(device)\n                with torch.inference_mode(), torch.autocast(device.type, dtype=torch.float16, enabled=device.type == "cuda"):\n                    logits = model(prep(x, spec["res"]), mask).float()\n                p = torch.sigmoid(logits)[0].cpu().numpy()\n                if p.shape != (len(TARGETS),) or not np.isfinite(p).all():\n                    raise FloatingPointError("nonfinite or misshaped probabilities")\n                probs[k, item["i"]] = p\n            except Exception as exc:\n                model_failures[f"{spec[\'name\']}:{type(exc).__name__}"] += 1\n                print(f"study {item[\'i\']} model {spec[\'name\']} FAILED: {exc!r}", flush=True)\n        if n % 100 == 0:\n            print(f"processed {n}/{len(uids)} in {time.monotonic() - T0:.0f}s", flush=True)\n\n    ok = np.isfinite(probs).all(2)  # (model, study)\n    if not ok.any():\n        raise RuntimeError("no study could be predicted")\n    for k, (spec, _) in enumerate(models):\n        write_csv(OUT / f"probs_{spec[\'name\']}.csv", columns, uids, probs[k])\n    if len(models) == 1:\n        score = probs[0].copy()\n    else:  # per-model, per-finding rank percentile over the studies that model predicted\n        ranks = np.full(probs.shape, np.nan)\n        for k in range(len(models)):\n            if ok[k].any():\n                ranks[k, ok[k]] = rankdata(probs[k, ok[k]], axis=0) / ok[k].sum()\n        with np.errstate(invalid="ignore"):\n            score = np.nanmean(ranks, axis=0)\n    good = np.isfinite(score).all(1)\n    fallback = score[good].mean(0)\n    n_fallback = int((~good).sum())\n    name = "probs_" + CONFIG["models"][0]["name"] + ".csv"\n    if PARITY_UIDS is None:\n        score[~good] = fallback\n        name = "submission.csv"\n        write_csv(OUT / name, columns, uids, score)\n    summary = {"status": "complete", "mode": "parity" if PARITY_UIDS is not None else "submission",\n               "device": str(device), "studies": len(uids),\n               "studies_ok": states["ok"], "studies_degraded": states["degraded"],\n               "studies_failed": states["failed"], "studies_timed_out": timed_out,\n               "studies_mean_fallback": n_fallback, "model_failures": dict(model_failures),\n               "studies_per_model": {s["name"]: int(ok[k].sum()) for k, (s, _) in enumerate(models)},\n               "studies_with_all_models": int(ok.all(0).sum()), "fallback_vector": fallback.round(6).tolist(),\n               "errors": dict(errors), "transfer_syntaxes": dict(syntaxes),\n               "valid_windows_min_median_max": [min(windows), float(np.median(windows)), max(windows)] if windows else None,\n               "config": CONFIG["run"],\n               "output_sha256": sha256(OUT / name), "elapsed_s": round(time.monotonic() - T0, 1),\n               "gpu_peak_reserved_bytes": torch.cuda.max_memory_reserved() if device.type == "cuda" else 0}\n    (OUT / "v3_inference_summary.json").write_text(json.dumps(summary, indent=2) + "\\n")\n    print(json.dumps(summary), flush=True)\n\n\nif __name__ == "__main__":\n    main()\n', 'gpjw': '"""E12 reader: goodpjw2008 2.5D ConvNeXt reader (dataset goodpjw2008/rsna-knee-2-5d-convnext-reader, Apache-2.0).\n\nUses the dataset\'s own knee.py / preprocess.py / infer.py (DicomStudyDataset, load_models logic) unchanged; only the\nloop is ours: device-agnostic (CPU preflight), batch 1 so a failure costs one study, fp16 autocast on CUDA only,\ndeadline guard. 3 folds averaged (as infer.run). pylibjpeg wheels from the dataset go to a private --target dir.\nWrites <E12_OUT>/reader_probs.csv (NaN = failed / not reached) and reader_info.json.\n"""\nimport glob, json, os, subprocess, sys, time\nimport numpy as np\n\nOUT = os.environ.get("E12_OUT", ".")\nDEADLINE = float(os.environ.get("E12_DEADLINE", time.time() + 1e9))\nT0 = time.time()\nK = 12  # infer.run default\nDS = next((d for d in ("/kaggle/input/rsna-knee-2-5d-convnext-reader",\n                       "/kaggle/input/datasets/goodpjw2008/rsna-knee-2-5d-convnext-reader")\n           if os.path.isdir(d)), None) or os.path.dirname(glob.glob("/kaggle/input/**/cnxt_v0_fold0.pt", recursive=True)[0])\nDS = os.path.dirname(glob.glob(f"{DS}/**/knee.py", recursive=True)[0])\nSITE = os.path.join(OUT, "site")\npy = f"cp{sys.version_info.major}{sys.version_info.minor}"\nwhl = [w for w in glob.glob(f"{DS}/*.whl") if py in w or "py3-none" in w]\npip = subprocess.run([sys.executable, "-m", "pip", "install", "-q", "--no-index", "--no-deps", "--target", SITE, *whl],\n                     capture_output=True, text=True) if whl else None\nsys.path[:0] = [DS, SITE]\n\nimport pandas as pd  # noqa: E402\nimport torch  # noqa: E402\nfrom infer import DicomStudyDataset  # noqa: E402\nfrom knee import LABELS, KneeNet, build_study_table  # noqa: E402\nfrom preprocess import MAX_SLICES  # noqa: E402\n\n\ndef main():\n    root = sys.argv[1]\n    dev = torch.device("cuda" if torch.cuda.is_available() else "cpu")\n    studies = pd.read_csv(f"{root}/test.csv").StudyInstanceUID.astype(str).tolist()\n    se = pd.read_csv(f"{root}/test_series.csv").astype({"StudyInstanceUID": str, "SeriesInstanceUID": str})\n    se = se[se.StudyInstanceUID.isin(set(studies))]\n    n_files = {}\n    for st, sr in zip(se.StudyInstanceUID, se.SeriesInstanceUID):\n        d = f"{root}/test_series/{st}/{sr}"\n        n_files[sr] = min(len(os.listdir(d)), MAX_SLICES) if os.path.isdir(d) else 0\n    ds = DicomStudyDataset(studies, build_study_table(se, n_files), f"{root}/test_series", K)\n    dl = torch.utils.data.DataLoader(ds, batch_size=1, num_workers=4, pin_memory=dev.type == "cuda")\n    models = []\n    for path in sorted(glob.glob(f"{DS}/cnxt_v0_fold*.pt")):\n        ck = torch.load(path, map_location="cpu", weights_only=False)\n        m = KneeNet(ck["args"]["backbone"].split(".")[0], pretrained=False)\n        m.load_state_dict(ck["model"])\n        models.append((m.to(dev).to(memory_format=torch.channels_last).eval(), ck["args"]["res"]))\n    t_loop = time.time()\n    probs, fails, notes = np.full((len(studies), 12), np.nan), 0, []\n    for i, (x, mask, pos) in enumerate(dl):\n        if time.time() > DEADLINE:\n            notes.append(f"deadline hit at study {i}; {len(studies) - i} left NaN"); break\n        try:\n            x, mask, pos = x.to(dev), mask.to(dev), pos.to(dev)\n            if not bool(mask.any()):\n                raise ValueError("no usable series")\n            with torch.no_grad(), torch.autocast("cuda", dtype=torch.float16, enabled=dev.type == "cuda"):\n                p = torch.stack([m(x, mask, pos, res=r).float().sigmoid() for m, r in models]).mean(0)[0].cpu().numpy()\n            if not np.isfinite(p).all():\n                raise FloatingPointError("nonfinite")\n            probs[i] = p\n        except Exception as e:\n            fails += 1\n            print(f"gpjw study {i} FAILED {type(e).__name__}: {e}", flush=True)\n        if (i + 1) % 100 == 0:\n            print(f"gpjw {i + 1}/{len(studies)} {time.time() - T0:.0f}s", flush=True)\n    pd.DataFrame(probs, columns=LABELS).assign(StudyInstanceUID=studies)[["StudyInstanceUID"] + LABELS].to_csv(f"{OUT}/reader_probs.csv", index=False)\n    import hashlib\n    json.dump({"sha256": {os.path.basename(f): hashlib.sha256(open(f, "rb").read()).hexdigest() for f in sorted(glob.glob(f"{DS}/cnxt_v0_fold*.pt"))},\n               "device": str(dev), "folds": len(models), "k": K, "failures": fails, "notes": notes,\n               "pip_wheels": [os.path.basename(w) for w in whl], "pip_rc": pip.returncode if pip else None,\n               "loop_s": round(time.time() - t_loop, 1), "elapsed_s": round(time.time() - T0, 1)}, open(f"{OUT}/reader_info.json", "w"))\n\n\nif __name__ == "__main__":\n    main()\n', 'raptor': '"""E12 reader: dreaddevelopment Raptor CoAtNet maxspan (dataset dreaddevelopment/raptor-knee-maxspan, CC0).\n\nModel + preprocessing adapted from the public notebook dreaddevelopment/knee-mri-twelve-findings-from-a-single-model\n(Apache-2.0), with the maxspan corpus settings used by rjings/rsna-versia-8: IMG 336, span 2-98 %, 64 slices,\n62 eval windows, res 384. Writes <E12_OUT>/reader_probs.csv (NaN row = study failed / not reached) and reader_info.json.\nDeadline guard: after WINDOW_CHECK_AT studies the projected time is compared with E12_DEADLINE (epoch s); if too slow,\nK_EVAL is cut (noted in reader_info); at the deadline the loop stops and the remaining studies stay NaN.\n"""\nimport csv, gc, glob, json, os, sys, time\nimport numpy as np\nimport torch, torch.nn as nn, torch.nn.functional as F\nimport timm\n\ntorch.backends.cudnn.benchmark = True\nOUT = os.environ.get("E12_OUT", ".")\nDEADLINE = float(os.environ.get("E12_DEADLINE", time.time() + 1e9))\nT0 = time.time()\nFILE, ARCH, RES = "raptor_ft_coatnet_v5_full_swa.pt", "coatnet_rmlp_2_rw_384.sw_in12k_ft_in1k", 384\nIMG, CROP_MM, SPAN = 336, 140.0, (0.02, 0.98)\nSLOTS = [("Sagittal", 1, 18), ("Sagittal", 0, 14), ("Coronal", 1, 12), ("Coronal", 0, 8), ("Axial", -1, 12)]\nMAXS = sum(s[2] for s in SLOTS)  # 64\nK_EVAL, K_MIN, WINDOW_CHECK_AT = 62, 16, 20\nLAB = ["ACL", "MCL", "Medial Meniscus", "Lateral Meniscus", "Medial OA", "Lateral OA",\n       "PF OA", "Effusion", "Synovitis", "Baker\'s", "Contusion", "Fracture"]\n_MEAN = torch.tensor([0.485, 0.456, 0.406]).view(3, 1, 1)\n_STD = torch.tensor([0.229, 0.224, 0.225]).view(3, 1, 1)\n\n\nclass RaptorClassifier(nn.Module):\n    def __init__(self, backbone, F_dim=768, n=12, drop=0.2):\n        super().__init__()\n        self.backbone = backbone\n        self.norm = nn.LayerNorm(F_dim)\n        self.att = nn.Sequential(nn.Linear(F_dim, 256), nn.Tanh(), nn.Dropout(drop), nn.Linear(256, n))\n        self.clsW = nn.Parameter(torch.zeros(n, F_dim))\n        self.clsb = nn.Parameter(torch.zeros(n))\n\n    def forward(self, x):\n        B, K = x.shape[:2]\n        h = self.norm(self.backbone(x.flatten(0, 1)).view(B, K, -1))\n        a = torch.softmax(self.att(h), dim=1)\n        return (torch.einsum("bkn,bkf->bnf", a, h) * self.clsW).sum(-1) + self.clsb\n\n\ndef eval_windows(vol, mask, k, res):\n    D = vol.shape[0]\n    valid = np.where(mask > 0)[0]\n    if len(valid) < 3:\n        valid = np.arange(min(3, D))\n    lo, hi = int(valid.min()), int(valid.max())\n    cs = [c for c in range(lo + 1, hi)] or [max(1, min((lo + hi) // 2, D - 2))]\n    cs = [cs[i] for i in np.linspace(0, len(cs) - 1, k).round().astype(int)]\n    wins = np.empty((len(cs), 3, res, res), np.float32)\n    for j, c in enumerate(cs):\n        c = max(1, min(c, D - 2))\n        t = torch.from_numpy(np.stack([vol[c - 1], vol[c], vol[c + 1]], 0).astype(np.float32) / 255.0)\n        if t.shape[-1] != res:\n            t = F.interpolate(t[None], size=(res, res), mode="bilinear", align_corners=False)[0]\n        wins[j] = t.numpy()\n    return (torch.from_numpy(wins) - _MEAN) / _STD\n\n\ndef make_reader():\n    import pydicom, cv2\n    from pydicom.pixel_data_handlers.util import apply_modality_lut\n\n    def order_and_meta(sdir):\n        recs, ps_list = [], []\n        for f in glob.glob(sdir + "/*.dcm"):\n            try:\n                h = pydicom.dcmread(f, stop_before_pixels=True)\n                iop, ipp = getattr(h, "ImageOrientationPatient", None), getattr(h, "ImagePositionPatient", None)\n                if iop is not None and ipp is not None and len(iop) == 6:\n                    pos = float(np.dot(np.array(ipp, float), np.cross(np.array(iop[:3], float), np.array(iop[3:], float))))\n                else:\n                    pos = float(getattr(h, "InstanceNumber", 0) or 0)\n                ps = getattr(h, "PixelSpacing", None)\n                ps = float(ps[0]) if ps is not None else 0.5\n                ps_list.append(ps); recs.append((pos, f, ps))\n            except Exception:\n                recs.append((0.0, f, 0.5))\n        recs.sort(key=lambda x: x[0])\n        return [(f, ps) for _, f, ps in recs], (float(np.median(ps_list)) if ps_list else 0.5)\n\n    def read_px(f):\n        d = pydicom.dcmread(f)\n        a = apply_modality_lut(d.pixel_array, d).astype(np.float32)\n        return a.max() - a if str(getattr(d, "PhotometricInterpretation", "")) == "MONOCHROME1" else a\n\n    def crop(a, ps):\n        h, w = a.shape\n        cpx = min(int(round(CROP_MM / max(ps, 1e-3))), h, w)\n        y0, x0 = (h - cpx) // 2, (w - cpx) // 2\n        return cv2.resize(a[y0:y0 + cpx, x0:x0 + cpx], (IMG, IMG), interpolation=cv2.INTER_AREA)\n    return order_and_meta, read_px, crop\n\n\ndef pick(rows, plane, fluid, used):\n    c = [r for r in rows if r["Anatomical_Plane"] == plane and r["SeriesInstanceUID"] not in used]\n    if fluid in (0, 1):\n        pref = [r for r in c if int(r.get("Fluid_Sensitive", 0) or 0) == fluid]\n        if pref:\n            return pref[0]\n    return c[0] if c else None\n\n\ndef build_study(sid, ser, tsdir, reader):\n    order_and_meta, read_px, crop = reader\n    vol, idx, used = np.zeros((MAXS, IMG, IMG), np.uint8), 0, set()\n    for plane, fluid, k in SLOTS:\n        r = pick(ser.get(sid, []), plane, fluid, used)\n        if r is None:\n            idx += k; continue\n        used.add(r["SeriesInstanceUID"])\n        files, med_ps = order_and_meta(f"{tsdir}/{sid}/{r[\'SeriesInstanceUID\']}")\n        if not files:\n            idx += k; continue\n        n = len(files)\n        lo, hi = int(n * SPAN[0]), max(int(n * SPAN[1]) - 1, int(n * SPAN[0]))\n        picks = np.linspace(lo, hi, k).round().astype(int) if n > 1 else [0] * k\n        arrs, pss = [], []\n        for p in picks:\n            fp, ps = files[min(p, n - 1)]\n            try:\n                arrs.append(read_px(fp)); pss.append(ps)\n            except Exception:\n                arrs.append(None); pss.append(med_ps)\n        valid = [a for a in arrs if a is not None]\n        loq, hiq = np.percentile(np.concatenate([a.ravel() for a in valid]), [2.0, 98.0]) if valid else (0.0, 1.0)\n        for a, ps in zip(arrs, pss):\n            if idx >= MAXS:\n                break\n            if a is not None:\n                vol[idx] = (crop(np.clip((a - loq) / (hiq - loq + 1e-6), 0, 1), ps if ps > 0 else med_ps) * 255).astype(np.uint8)\n            idx += 1\n    return vol, (vol.reshape(MAXS, -1).sum(1) > 0).astype(np.uint8)\n\n\ndef find_weights():\n    for p in ("/kaggle/input/raptor-knee-maxspan", "/kaggle/input/datasets/dreaddevelopment/raptor-knee-maxspan"):\n        hits = glob.glob(f"{p}/**/{FILE}", recursive=True)\n        if hits:\n            return hits[0]\n    for d in glob.glob("/kaggle/input/*/") + glob.glob("/kaggle/input/datasets/*/*/"):\n        if "competition" not in d:\n            hits = glob.glob(f"{d}**/{FILE}", recursive=True)\n            if hits:\n                return hits[0]\n    raise FileNotFoundError(FILE)\n\n\ndef main():\n    import pandas as pd\n    root = sys.argv[1]\n    dev = "cuda" if torch.cuda.is_available() else "cpu"\n    ids = pd.read_csv(f"{root}/test.csv")["StudyInstanceUID"].astype(str).tolist()\n    tser = pd.read_csv(f"{root}/test_series.csv").astype({"StudyInstanceUID": str, "SeriesInstanceUID": str})\n    ser = {k: v.to_dict("records") for k, v in tser.groupby("StudyInstanceUID")}\n    wpath = find_weights()\n    import hashlib\n    wsha = hashlib.sha256(open(wpath, "rb").read()).hexdigest()\n    ck = torch.load(wpath, map_location="cpu", weights_only=False)\n    bb = timm.create_model(ck.get("arch", ARCH), pretrained=False, num_classes=0, in_chans=3, global_pool="avg")\n    model = RaptorClassifier(bb, F_dim=bb.num_features)\n    model.load_state_dict(ck["model"], strict=True)\n    model.eval().to(dev)\n    res = int(ck.get("res", RES)); del ck; gc.collect()\n    k, notes, fails, t_loop = K_EVAL, [], 0, time.time()\n    probs = np.full((len(ids), 12), np.nan)\n    for i, sid in enumerate(ids):\n        if time.time() > DEADLINE:\n            notes.append(f"deadline hit at study {i}; {len(ids) - i} left NaN"); break\n        if i == WINDOW_CHECK_AT and len(ids) > 2 * WINDOW_CHECK_AT:\n            per = (time.time() - t_loop) / i\n            need, left = per * (len(ids) - i), DEADLINE - time.time()\n            if need > left:\n                k = max(K_MIN, int(k * left / need * 0.9))\n                notes.append(f"windows reduced {K_EVAL}->{k} at study {i} (projected {need:.0f}s > left {left:.0f}s)")\n        try:\n            vol, mask = build_study(sid, ser, f"{root}/test_series", reader)\n            x = eval_windows(vol, mask, k, res)[None].to(dev)\n            with torch.no_grad(), torch.autocast("cuda", dtype=torch.float16, enabled=dev == "cuda"):\n                p = torch.sigmoid(model(x).float())[0].cpu().numpy()\n            if not np.isfinite(p).all():\n                raise FloatingPointError("nonfinite")\n            probs[i] = p\n        except Exception as e:\n            fails += 1\n            print(f"raptor study {i} FAILED {type(e).__name__}: {e}", flush=True)\n        if (i + 1) % 100 == 0:\n            print(f"raptor {i + 1}/{len(ids)} {time.time() - T0:.0f}s", flush=True)\n    pd.DataFrame(probs, columns=LAB).assign(StudyInstanceUID=ids)[["StudyInstanceUID"] + LAB].to_csv(f"{OUT}/reader_probs.csv", index=False)\n    json.dump({"weights": wpath, "sha256": wsha, "device": dev, "k_eval_final": k, "failures": fails, "notes": notes, "loop_s": round(time.time() - t_loop, 1), "elapsed_s": round(time.time() - T0, 1)},\n              open(f"{OUT}/reader_info.json", "w"))\n\n\nreader = make_reader()\nif __name__ == "__main__":\n    main()\n'}
WORK = Path("/kaggle/working") if Path("/kaggle/working").is_dir() else Path(".")
ROOT = next(p for p in ("/kaggle/input/rsna-knee-abnormality-detection",
                        "/kaggle/input/competitions/rsna-knee-abnormality-detection") if os.path.isfile(p + "/test.csv"))


def run_reader(name):
    out = WORK / "e12" / name
    out.mkdir(parents=True, exist_ok=True)
    script = out / f"{name}_reader.py"
    script.write_text(SOURCES[name], encoding="utf-8")
    env = dict(os.environ, E12_OUT=str(out), E12_DEADLINE=str(DEADLINE - 600))
    t = time.time()
    try:
        r = subprocess.run([sys.executable, str(script), ROOT], cwd=out, env=env,
                           timeout=max(60, DEADLINE - time.time()), capture_output=True, text=True)
        rc, log = r.returncode, r.stdout + r.stderr
    except subprocess.TimeoutExpired as e:
        rc, log = "timeout", str(e.stdout or "") + str(e.stderr or "")
    (out / "log.txt").write_text(log, encoding="utf-8")
    print(f"--- {name} rc={rc} {time.time() - t:.0f}s\n{log[-3000:]}", flush=True)
    return out, rc, round(time.time() - t, 1)


def main():
    import numpy as np
    import pandas as pd
    from scipy.stats import rankdata
    cols = list(pd.read_csv(ROOT + "/sample_submission.csv", nrows=1).columns)
    labs = cols[1:]
    uids = pd.read_csv(ROOT + "/test.csv")["StudyInstanceUID"].astype(str).tolist()
    n = len(uids)
    summary = {"weights": WEIGHTS, "studies": n, "readers": {}}
    scores = {}
    for name in ORDER:
        out, rc, sec = run_reader(name)
        info = {"rc": rc, "runtime_s": sec, "s_per_study": round(sec / max(n, 1), 2)}
        try:
            if name == "ens4":  # per-model probs -> per-model rank pct -> mean over models that succeeded
                s = json.loads((out / "v3_inference_summary.json").read_text())
                info["inner"] = {k: s.get(k) for k in ("studies_failed", "studies_timed_out", "model_failures",
                                                       "studies_per_model", "device")}
                rk = []
                for f in sorted(out.glob("probs_*.csv")):
                    p = pd.read_csv(f, dtype={"StudyInstanceUID": str}).set_index("StudyInstanceUID").reindex(uids)[labs].to_numpy(float)
                    ok = np.isfinite(p).all(1)
                    r = np.full(p.shape, np.nan)
                    if ok.any():
                        r[ok] = rankdata(p[ok], axis=0) / ok.sum()
                    rk.append(r)
                with np.errstate(invalid="ignore"):
                    p = np.nanmean(np.stack(rk), 0)
            else:
                info["inner"] = json.loads((out / "reader_info.json").read_text())
                p = pd.read_csv(out / "reader_probs.csv", dtype={"StudyInstanceUID": str}).set_index("StudyInstanceUID").reindex(uids)[labs].to_numpy(float)
            ok = np.isfinite(p).all(1)
            info["studies_ok"], info["studies_failed"] = int(ok.sum()), int(n - ok.sum())
            if ok.any():
                r = np.full(p.shape, np.nan)
                r[ok] = rankdata(p[ok], axis=0) / ok.sum()
                scores[name] = r
        except Exception as e:
            info["error"] = f"{type(e).__name__}: {e}"
            info["studies_ok"], info["studies_failed"] = 0, n
        summary["readers"][name] = info
        print(name, json.dumps(info, default=str), flush=True)
    if not scores:
        raise RuntimeError("no reader produced predictions")
    num, den = np.zeros((n, len(labs))), np.zeros((n, 1))
    for name, r in scores.items():
        ok = np.isfinite(r).all(1, keepdims=True)
        num += np.where(ok, r, 0) * WEIGHTS[name]
        den += ok * WEIGHTS[name]
    with np.errstate(invalid="ignore"):
        score = num / den
    good = den[:, 0] > 0
    score[~good] = score[good].mean(0)
    readers_per_study = sum(np.isfinite(r).all(1).astype(int) for r in scores.values())
    summary.update(studies_no_reader=int((~good).sum()),
                   studies_by_n_readers={str(k): int((readers_per_study == k).sum()) for k in range(len(ORDER) + 1)},
                   elapsed_s=round(time.time() - T0, 1))
    sub = pd.DataFrame(score, columns=labs)
    sub.insert(0, "StudyInstanceUID", uids)
    assert list(sub.columns) == cols and np.isfinite(sub[labs].to_numpy()).all()
    sub.to_csv(WORK / "submission.csv", index=False)
    (WORK / "e12_summary.json").write_text(json.dumps(summary, indent=2, default=str))
    print(json.dumps(summary, default=str), flush=True)


if __name__ == "__main__":
    main()
